# Read–modify–write with optimistic CAS and a 1-hour TTL.
from executa_sdk import ctx

async def remember_search(query: str) -> None:
    cur = await ctx.storage.get(key="search.last")
    state = cur["value"] if cur["exists"] else {"history": []}
    state["history"] = ([query] + state["history"])[:50]
    try:
        resp = await ctx.storage.set(
            key="search.last",
            value=state,
            if_match=cur["etag"],   # None on first create is fine
            tags=["recents"],
            ttl_seconds=3600,        # forget after 1 h of no writes
        )
    except RpcError as e:
        if e.code == STORAGE_ERR_PRECONDITION_FAILED:
            # Someone else wrote between our get and set — retry the whole RMW.
            return await remember_search(query)
        raise
    # resp == {'etag': '…', 'generation': 7, 'size_bytes': 412}

# Clear a per-conversation cursor, but only if it hasn't changed since we read it.
from executa_sdk import ctx

async def forget_cursor(conversation_id: str) -> bool:
    key = f"cursor.{conversation_id}"
    cur = await ctx.storage.get(key=key)
    if not cur["exists"]:
        return False                       # nothing to do
    try:
        await ctx.storage.delete(key=key, if_match=cur["etag"])
    except RpcError as e:
        if e.code == STORAGE_ERR_PRECONDITION_FAILED:
            return False                   # someone else wrote first
        if e.code == STORAGE_ERR_NOT_FOUND:
            return False                   # already gone
        raise
    return True

# Page through every key under a prefix and drop the stale ones.
from executa_sdk import ctx

async def gc_drafts(stale_before: str) -> int:
    removed, cursor = 0, None
    while True:
        page = await ctx.storage.list(
            prefix="draft/",
            cursor=cursor,
            limit=200,
        )
        for item in page["items"]:
            if item["updated_at"] < stale_before:
                try:
                    await ctx.storage.delete(
                        key=item["key"],
                        if_match=item["etag"],
                    )
                    removed += 1
                except RpcError as e:
                    if e.code not in (
                        STORAGE_ERR_PRECONDITION_FAILED,
                        STORAGE_ERR_NOT_FOUND,
                    ):
                        raise
        cursor = page["next_cursor"]
        if not cursor:
            break
    return removed

# Build a JSON index of every PDF in this anna-app's storage, regardless of size.
from executa_sdk import ctx

async def index_pdfs() -> list[dict]:
    out, cursor = [], None
    while True:
        page = await ctx.storage.files.list(
            prefix="reports/",
            cursor=cursor,
            limit=200,
            scope="app",
        )
        for item in page["items"]:
            # Filter pending uploads client-side (see Limitations).
            if (item.get("metadata") or {}).get("__pending"):
                continue
            if item["content_type"] == "application/pdf":
                out.append({
                    "path": item["path"],
                    "size_bytes": item["size_bytes"],
                    "updated_at": item["updated_at"],
                })
        cursor = page["next_cursor"]
        if not cursor:
            break
    return out

# Drop every object under a stale prefix.
from executa_sdk import ctx

async def purge_drafts(prefix: str = "drafts/") -> int:
    removed, cursor = 0, None
    while True:
        page = await ctx.storage.files.list(
            prefix=prefix, cursor=cursor, limit=200, scope="app",
        )
        for item in page["items"]:
            try:
                await ctx.storage.files.delete(path=item["path"], scope="app")
                removed += 1
            except RpcError as e:
                if e.code != STORAGE_ERR_NOT_FOUND:
                    raise   # someone else already tombstoned this path — fine
        cursor = page["next_cursor"]
        if not cursor:
            break
    return removed
